var forbiddenSpells = (state) => plannedSpells.filter((spell) => spell.tier === "advanced" && spell.available && !acquiredItemIds(state).has(spell.id));
function choiceRoomBlock(state, id) {
	if (state.hp <= 0 || state.combat?.status === "active") return "지금은 거래할 수 없어요.";
	if (id === "soul-lantern") return state.soulLantern === "ready" ? "이미 불이 켜져 있어요." : playerMaxHp(state) < 30 ? "최대 체력 20을 남겨야 해요." : null;
	if (id === "forbidden-trade") return state.hp <= 50 ? "체력 51 이상 필요" : !forbiddenSpells(state).length ? "받을 중급 마법이 없어요." : null;
	if (id === "broken-teleport") return state.pendingFloorAdvance ? "이미 이동을 준비했어요." : !canUseTeleport(state.market.floor) ? "고정 방이 있는 구간은 이동할 수 없어요." : state.gold < 200 ? "골드 200 필요" : null;
	return null;
}
function acceptChoiceRoom(state, id, random = Math.random) {
	if (choiceRoomBlock(state, id)) return state;
	if (id === "soul-lantern") {
		const next = {
			...state,
			soulLantern: "ready",
			maxHpSacrifice: (state.maxHpSacrifice ?? 0) + 10
		};
		return {
			...next,
			hp: Math.min(state.hp, playerMaxHp(next))
		};
	}
	if (id === "deep-well") return {
		...state,
		hp: playerMaxHp(state),
		mp: 0
	};
	if (id === "cursed-gem-eye") return random() < .5 ? {
		...state,
		gold: state.gold + 500
	} : {
		...state,
		mp: Math.max(0, state.mp - 20)
	};
	if (id === "broken-teleport") return {
		...state,
		gold: state.gold - 200,
		pendingFloorAdvance: 3
	};
	const pool = forbiddenSpells(state), spell = pool[Math.min(pool.length - 1, Math.floor(random() * pool.length))];
	return {
		...state,
		hp: state.hp - 50,
		acquiredIds: recordAcquired(state, spell.id),
		spells: [...state.spells, {
			...spell,
			message: spell.description
		}]
	};
}
