function merchantTierChances(floor) {
	const level = Math.min(100, Math.max(1, Math.floor(Number.isFinite(floor) ? floor : 1)));
	return merchantTierBands.find((band) => level <= band.through);
}
function drawTieredOffers(items, floor, random, count = 3) {
	const chances = merchantTierChances(floor), selected = [];
	for (let slot = 0; slot < count; slot++) {
		const roll = random() * 100;
		const tier = roll < chances.ultimate ? "ultimate" : roll < chances.ultimate + chances.advanced ? "advanced" : "starter";
		const pool = items.filter((item) => item.tier === tier && !selected.includes(item.id));
		if (!pool.length) continue;
		selected.push(pool[Math.min(pool.length - 1, Math.floor(random() * pool.length))].id);
	}
	return selected;
}
function drawFloorMarket(floor, random = Math.random) {
	const doors = [
		"monster",
		"monster",
		"sphinx"
	];
	if (floor > 1 && random() * 100 < 20) doors[Math.min(2, Math.floor(random() * 3))] = "merchant-hasan";
	return {
		floor,
		doors,
		weaponIds: drawTieredOffers(explorationWeapons, floor, random, 5),
		armorIds: drawTieredOffers(explorationArmor, floor, random, 5)
	};
}
